insert into public.games (id, sort_order, title, about, badges, genres, platforms, statuses, socials, image_src, hero_src, rating, reviews_count) values
  ('tekken-8', 1, 'TEKKEN 8', 'TEKKEN 8 cierra la saga de los Mishima con el sistema Heat, que premia jugar agresivo. Treinta y dos luchadores, escenarios que se rompen y un modo Arcade Quest para aprender antes de entrar al online.', array['Pelea', '1v1'], array['accion'], array['pc', 'consola'], array['disponible'], array['youtube', 'twitch', 'x'], '/assets/games/catalog/tekken-8.webp', '/assets/games/catalog/tekken-8-hero.webp', 4.4, 53),
  ('marvel-rivals', 2, 'Marvel Rivals', 'Marvel Rivals es un hero shooter 6v6 con más de treinta personajes del universo Marvel y escenarios que se destruyen en plena partida. Armá combos de equipo y subí de rango en las temporadas competitivas.', array['Hero Shooter', 'Free-To-Play'], array['accion'], array['pc', 'consola'], array['disponible'], array['x', 'youtube', 'twitch'], '/assets/games/catalog/marvel-rivals.webp', '/assets/games/catalog/marvel-rivals-hero.webp', 4.6, 72),
  ('hollow-knight-silksong', 3, 'Hollow Knight: Silksong', 'En Silksong jugás como Hornet, princesa y protectora de Hallownest, en un reino nuevo hecho de seda y canción. Más de 150 enemigos, jefes que no perdonan y un mapa que se abre a medida que ganás habilidades.', array['Metroidvania', 'Un jugador'], array['aventura'], array['pc', 'consola'], array['disponible'], array['x', 'youtube'], '/assets/games/catalog/hollow-knight-silksong.webp', '/assets/games/catalog/hollow-knight-silksong-hero.webp', 4.4, 110),
  ('baldurs-gate-3', 4, 'Baldur''s Gate 3', 'Baldur''s Gate 3 es el RPG de Larian basado en Dungeons & Dragons: armás tu grupo, decidís cada conversación y cada tirada de dados cambia la historia. Se juega solo o en cooperativo con hasta cuatro amigos.', array['Por turnos', 'Cooperativo'], array['rpg'], array['pc', 'consola'], array['disponible'], array['x', 'youtube', 'instagram'], '/assets/games/catalog/baldurs-gate-3.webp', '/assets/games/catalog/baldurs-gate-3-hero.webp', 4.3, 172),
  ('fall-guys', 5, 'Fall Guys', 'Fall Guys es un party game de rondas eliminatorias: sesenta jugadores, obstáculos absurdos y una sola corona al final. Partidas cortas, ideales para sumar puntos entre torneo y torneo.', array['Party Game', 'Free-To-Play'], array['casual'], array['pc', 'consola', 'mobile'], array['disponible'], array['tiktok', 'instagram', 'x'], '/assets/games/catalog/fall-guys.webp', '/assets/games/catalog/fall-guys-hero.webp', 4.8, 137),
  ('counter-strike-2', 6, 'Counter-Strike 2', 'Counter-Strike 2 lleva el shooter táctico más jugado del mundo a Source 2: granadas de humo dinámicas, mapas rehechos y servidores con subtick. Es el juego de los torneos semanales de la comunidad.', array['Shooter táctico', '5v5'], array['accion'], array['pc'], array['disponible'], array['discord', 'twitch', 'x'], '/assets/games/catalog/counter-strike-2.webp', '/assets/games/catalog/counter-strike-2-hero.webp', 4.2, 157),
  ('league-of-legends', 7, 'League of Legends', 'League of Legends es el MOBA de Riot: dos equipos de cinco campeones pelean por destruir el Nexo enemigo en la Grieta del Invocador. Más de 170 campeones, una temporada competitiva cada año y la escena de esports más grande del mundo.', array['MOBA', '5v5'], array['estrategia', 'accion'], array['pc'], array['disponible'], array['youtube', 'x', 'twitch'], '/assets/games/catalog/league-of-legends.webp', '/assets/games/catalog/league-of-legends-hero.webp', 4.3, 167),
  ('clair-obscur-expedition-33', 8, 'Clair Obscur: Expedition 33', 'Clair Obscur: Expedition 33 es un RPG por turnos con reflejos en tiempo real: esquivás y contraatacás en cada golpe. Liderás la expedición que sale a destruir a la Pintora antes de que vuelva a borrar a tu gente.', array['Por turnos', 'Un jugador'], array['rpg'], array['pc', 'consola'], array['disponible'], array['x', 'youtube'], '/assets/games/catalog/clair-obscur-expedition-33.webp', '/assets/games/catalog/clair-obscur-expedition-33-hero.webp', 4.6, 162),
  ('apex-legends', 9, 'Apex Legends', 'Apex Legends es un battle royale por escuadras donde cada leyenda tiene habilidades propias. Movilidad rápida, peleas en equipo y una temporada nueva cada tres meses con mapas y armas.', array['Battle Royale', 'Free-To-Play'], array['accion'], array['pc', 'consola'], array['disponible'], array['x', 'twitch', 'youtube'], '/assets/games/catalog/apex-legends.webp', '/assets/games/catalog/apex-legends-hero.webp', 4.6, 219),
  ('hades-ii', 10, 'Hades II', 'En Hades II sos Melinoë, princesa del Inframundo, y tenés que derrotar al Titán del Tiempo. Cada intento es distinto: bendiciones de los dioses, armas nuevas y conjuros que se combinan de mil formas.', array['Roguelike', 'Un jugador'], array['accion', 'rpg'], array['pc', 'consola'], array['disponible'], array['x', 'youtube'], '/assets/games/catalog/hades-ii.webp', '/assets/games/catalog/hades-ii-hero.webp', 4.3, 190),
  ('street-fighter-6', 11, 'Street Fighter 6', 'Street Fighter 6 suma el sistema Drive y controles modernos para que cualquiera pueda entrar al competitivo. Es el juego de las Noches de Duelos: se juega a dos de tres y el ganador sigue en la mesa.', array['Pelea', '1v1'], array['accion'], array['pc', 'consola'], array['disponible'], array['twitch', 'youtube', 'x'], '/assets/games/catalog/street-fighter-6.webp', '/assets/games/catalog/street-fighter-6-hero.webp', 4.3, 102),
  ('age-of-empires-iv', 12, 'Age of Empires IV', 'Age of Empires IV es estrategia en tiempo real clásica: juntás recursos, avanzás de edad y llevás tu civilización a la guerra. Dieciséis civilizaciones, cada una con unidades y maravillas propias.', array['Tiempo real', 'Multijugador'], array['estrategia'], array['pc', 'consola'], array['disponible'], array['youtube', 'discord'], '/assets/games/catalog/age-of-empires-iv.webp', '/assets/games/catalog/age-of-empires-iv-hero.webp', 4.2, 222),
  ('palworld', 13, 'Palworld', 'Palworld mezcla supervivencia, crafteo y criaturas: capturás Pals, los ponés a trabajar en tu base y salís a explorar con ellos. Se juega solo o con hasta 32 jugadores en un servidor propio.', array['Supervivencia', 'Cooperativo'], array['aventura'], array['pc', 'consola'], array['disponible'], array['x', 'discord', 'tiktok'], '/assets/games/catalog/palworld.webp', '/assets/games/catalog/palworld-hero.webp', 4.2, 212),
  ('split-fiction', 14, 'Split Fiction', 'Split Fiction es una aventura sólo para dos: Mio y Zoe quedan atrapadas en sus propias historias, una de ciencia ficción y otra de fantasía. Cada nivel cambia las reglas y ninguno se puede pasar solo.', array['Cooperativo', 'Pantalla dividida'], array['aventura'], array['pc', 'consola'], array['proximamente'], array['instagram', 'youtube'], '/assets/games/catalog/split-fiction.webp', '/assets/games/catalog/split-fiction-hero.webp', 4.5, 190),
  ('the-finals', 15, 'THE FINALS', 'THE FINALS es un shooter por equipos en un game show virtual donde todo el escenario se puede romper. Tirás una pared, abrís un piso o volás el edificio entero para llegar primero a la bóveda.', array['Shooter', 'Free-To-Play'], array['accion'], array['pc', 'consola'], array['disponible'], array['x', 'twitch'], '/assets/games/catalog/the-finals.webp', '/assets/games/catalog/the-finals-hero.webp', 4.5, 167),
  ('rematch', 16, 'REMATCH', 'REMATCH es fútbol arcade en tercera persona: controlás a un solo jugador, sin faltas ni fuera de juego, en partidos de cinco contra cinco. Pases, gambetas y atajadas dependen sólo de tu habilidad.', array['Fútbol', '5v5'], array['casual'], array['pc', 'consola'], array['beta'], array['tiktok', 'instagram', 'x'], '/assets/games/catalog/rematch.webp', '/assets/games/catalog/rematch-hero.webp', 4.9, 104),
  ('monster-hunter-wilds', 17, 'Monster Hunter Wilds', 'Monster Hunter Wilds te manda a las Tierras Prohibidas, un mundo abierto con clima que cambia y monstruos que migran. Salís de caza solo o con tres amigos, y con cada presa forjás equipo más fuerte.', array['Caza', 'Cooperativo'], array['rpg', 'accion'], array['pc', 'consola'], array['proximamente'], array['youtube', 'x'], '/assets/games/catalog/monster-hunter-wilds.webp', '/assets/games/catalog/monster-hunter-wilds-hero.webp', 4.8, 13),
  ('black-myth-wukong', 18, 'Black Myth: Wukong', 'Black Myth: Wukong es un RPG de acción basado en Viaje al Oeste: sos el Destinado y peleás contra criaturas de la mitología china. Transformaciones, hechizos y jefes que te obligan a aprender cada movimiento.', array['Soulslike', 'Un jugador'], array['accion', 'aventura'], array['pc', 'consola'], array['disponible'], array['youtube', 'instagram'], '/assets/games/catalog/black-myth-wukong.webp', '/assets/games/catalog/black-myth-wukong-hero.webp', 4.8, 145),
  ('helldivers-2', 19, 'Helldivers 2', 'En Helldivers 2 formás un escuadrón de cuatro para llevar la democracia gestionada a la galaxia. Fuego amigo siempre activo, estratagemas desde la órbita y una guerra que la comunidad gana o pierde junta.', array['Cooperativo', 'Shooter'], array['accion'], array['pc', 'consola'], array['disponible'], array['discord', 'x', 'tiktok'], '/assets/games/catalog/helldivers-2.webp', '/assets/games/catalog/helldivers-2-hero.webp', 4.5, 251),
  ('dota-2', 20, 'Dota 2', 'Dota 2 es el MOBA de Valve: dos equipos de cinco, más de cien héroes y un mapa que se decide torre por torre. Cada parche cambia el meta, y siempre hay una estrategia nueva para probar.', array['MOBA', 'Free-To-Play'], array['estrategia'], array['pc'], array['disponible'], array['twitch', 'youtube'], '/assets/games/catalog/dota-2.webp', '/assets/games/catalog/dota-2-hero.webp', 4.8, 237),
  ('among-us', 21, 'Among Us', 'En Among Us la tripulación hace tareas mientras los impostores sabotean la nave. Se juega hablando: sospechás, acusás y votás a quién tirar por la escotilla antes de que sea tarde.', array['Party Game', 'Deducción'], array['casual'], array['pc', 'consola', 'mobile'], array['disponible'], array['tiktok', 'discord'], '/assets/games/catalog/among-us.webp', '/assets/games/catalog/among-us-hero.webp', 4.4, 245),
  ('civilization-vii', 22, 'Civilization VII', 'Civilization VII divide la historia en tres eras y te deja cambiar de civilización al pasar de una a otra. Fundás ciudades, negociás con líderes históricos y elegís cómo ganar: ciencia, cultura, economía o guerra.', array['Por turnos', '4X'], array['estrategia'], array['pc', 'consola'], array['disponible'], array['x', 'youtube'], '/assets/games/catalog/civilization-vii.webp', '/assets/games/catalog/civilization-vii-hero.webp', 4.9, 164),
  ('rocket-league', 23, 'Rocket League', 'Rocket League es fútbol con autos cohete: saltás, volás y le pegás a una pelota gigante en partidos de cinco minutos. Fácil de entender y muy difícil de dominar, ideal para ligas por equipos.', array['Fútbol con autos', 'Free-To-Play'], array['casual'], array['pc', 'consola'], array['disponible'], array['twitch', 'tiktok', 'x'], '/assets/games/catalog/rocket-league.webp', '/assets/games/catalog/rocket-league-hero.webp', 4.4, 41),
  ('overwatch-2', 24, 'Overwatch 2', 'Overwatch 2 es un shooter por equipos de cinco donde cada héroe cumple un rol: tanque, daño o apoyo. Temporadas cada nueve semanas, con héroes, mapas y modos que se suman al competitivo.', array['Hero Shooter', '5v5'], array['accion'], array['pc', 'consola'], array['disponible'], array['x', 'youtube', 'twitch'], '/assets/games/catalog/overwatch-2.webp', '/assets/games/catalog/overwatch-2-hero.webp', 4.2, 105);
